<template><section class="demo-shell"><search><form class="toolbar" action="" method="get" @submit.prevent="search"><label for="filter-query">名称或编号<input id="filter-query" name="q" type="search" v-model="query" maxlength="100"></label><label for="filter-group">分组<select id="filter-group" name="group" v-model="group"><option value="">全部</option><option>A组</option><option>B组</option><option>C组</option></select></label><a-button html-type="submit"  @click="">查询</a-button><a-button html-type="button"  @click="reset">重置</a-button></form></search><div class="actions"><a-button html-type="button" id="create-record" @click="create">新增条目</a-button></div><form action="" method="post" @submit.prevent="save" v-if="editing" class="native-form"><fieldset class="edit-form"><legend>编辑演示条目</legend><label for="record-name">名称<input id="record-name" name="name" v-model="editing.name" required maxlength="60" pattern=".*\S.*"></label><label for="record-group">分组<select id="record-group" name="group" v-model="editing.group"><option>A组</option><option>B组</option><option>C组</option></select></label><label for="record-status">状态<select id="record-status" name="status" v-model="editing.status"><option>进行中</option><option>已完成</option></select></label><div class="actions"><button type="submit" class="primary">保存条目</button><button type="button" @click="cancelEdit">取消编辑</button></div></fieldset></form><p role="status" class="summary">{{notice}}</p><div class="split"><section><div class="table-scroll" tabindex="0" role="region" aria-label="演示数据，可横向滚动"><a-table :data-source="visibleRows" :columns="columns" :pagination="false" row-key="id" aria-label="演示数据表"><template #bodyCell="{column,record}"><div v-if="column.key==='actions'" class="actions"><button type="button" @click="choose(record)" :aria-label="'选择 '+record.code">选择</button><button type="button" @click="edit(record)" :aria-label="'编辑 '+record.code">编辑</button><button type="button" @click="remove(record)" :aria-label="'删除 '+record.code">删除</button></div><span v-else>{{record[column.dataIndex]}}</span></template></a-table></div><nav class="pagination" aria-label="演示数据分页"><button type="button" :disabled="page===1" @click="previous">上一页</button><span>第 {{page}} / {{pageCount}} 页 · {{filtered.length}} 条</span><button type="button" :disabled="page===pageCount" @click="next">下一页</button></nav></section><aside class="panel"><h2>当前选择</h2><p v-if="selected">{{selected.code}} · {{selected.name}}</p><p v-else>点击行或“选择”查看条目。</p><p class="note">数据为人工构造，操作只影响当前页面。</p></aside></div><chart-panel :rows="filtered"/></section></template><script>import options from './js/index.mjs';export default options;</script><style src="./css/index.css"></style>
